root=Path('/evidence/native');meta=json.loads(Path('/meta.json').read_bytes());source=meta['implementation_source_sha'];started=time.monotonic();blocks=[validate_block(root/str(j['seed_start']),expected_source=source) for j in meta['jobs']];values=[v for b in blocks for v in b['values']];expected_seeds=set(range(200001,203001));require(len(values)==36000 and len({(r['seed'],r['level'],r['profile']) for r in values})==36000,'Original full paired-seed denominator incomplete');means=[];tables=[];steps=[1,1,2,2,3,3];tenths=[10,14,18,22,26,30]
