 selected=[v for v in values if v['level']==L];require(len(selected)==6000 and {v['seed'] for v in selected}==expected_seeds,'Three original logical blocks missing');groups={p:[{'seed':v['seed'],'battle':'five-successful-plays','value':v['weapon_contribution']} for v in selected if v['profile']==p] for p in ['Baseline','Candidate']};stats=paired_clusters(groups['Baseline'],groups['Candidate']);base=[v['value'] for v in groups['Baseline']];cand=[v['value'] for v in groups['Candidate']];require(len(base)==len(cand)==3000 and set(base)=={5*steps[L]} and set(cand)=={tenths[L]//2},'Native current table differs');base_mean=sum(base)/(5*len(base));candidate_mean=sum(cand)/(5*len(cand));means.append((base_mean,candidate_mean));tables.append({'level':L,'paired_seeds':3000,'independent_blocks':[200001,201001,202001],'baseline_actual_weapon_mean_per_play':base_mean,'candidate_actual_weapon_mean_per_play':candidate_mean,'five_play_weapon_contribution':stats,'all_native_trace_states_independently_checked':True})
